#include <Arduino.h>
#include <Audio.h>
#include <Wire.h>
#include <SPI.h>

#include "drum_raw.h" // generated by create.py

AudioPlayMemory       playMem;
AudioOutputI2S        i2s1;
AudioControlSGTL5000  audioShield; // uncommented: will be used if present
AudioConnection       patchCord1(playMem, 0, i2s1, 0);
AudioConnection       patchCord2(playMem, 0, i2s1, 1);

void setup() {
  Serial.begin(115200);
  while (!Serial) { delay(10); }
  Serial.println("Playback test starting...");

  AudioMemory(50);

  // If you have the SGTL5000 audio shield, enable and set volume:
  audioShield.enable();
  audioShield.volume(0.8f);

  delay(50);

  // sanity check header values
  Serial.print("drum_raw_len (words): ");
  Serial.println(drum_raw_len);

  // Try to start playback once
  if (playMem.play(drum_raw) == 0) {
    Serial.println("playMem.play() returned 0 -> likely failed to start.");
  } else {
    Serial.println("play started.");
  }
}

void loop() {
  static unsigned long lastPrint = 0;

  if (millis() - lastPrint > 300) {
    lastPrint = millis();
    Serial.print("isPlaying: ");
    Serial.println(playMem.isPlaying() ? "YES" : "NO");
  }

  // If playback stopped, play again after a short pause
  if (!playMem.isPlaying()) {
    delay(250); // small gap
    Serial.println("Triggering playMem.play(drum_raw)");
    if (playMem.play(drum_raw) == 0) {
      Serial.println("play failed (0). Check drum_raw header and memory.");
      // don't spam attempts
      delay(1000);
    } else {
      Serial.println("play triggered.");
    }
  }

  delay(10);
}